    $('#feedback').textContent = error.message;
    $('#feedback').dataset.error = 'true';
    setBanner('error', '주문 요청을 처리하지 못했습니다', error.message);
  } finally {
    submitting = false;
    for (const button of document.querySelectorAll('button')) button.disabled = false;
  }
}

